    Bug 2030856 - Part 1: check if Thunderbird is the default mail client when closing account hub. r=aleca

    Differential Revision: https://phabricator.services.mozilla.com/D293946

diff --git a/mail/components/accountcreation/content/accountHub.js b/mail/components/accountcreation/content/accountHub.js
index 093fbf17c64..f66dc65dc92 100644
--- a/mail/components/accountcreation/content/accountHub.js
+++ b/mail/components/accountcreation/content/accountHub.js
@@ -93,6 +93,13 @@ class AccountHubControllerClass {
         event.stopPropagation();
         if (!this.#minimized && this.#reset()) {
           this.#modal.close();
+          // Check system integration once account hub is closed without
+          // blocking this event. This also allows account hub to clean up and
+          // avoid false-positives by having a temporary account in the profile.
+          window.requestIdleCallback(
+            () => window.showSystemIntegrationDialog(),
+            { timeout: 100 }
+          );
         }
       },
       {
